# -*- coding: utf-8 -*-
"""MANAPRINT — CIBLE · 8 numéros (création RANIHEI Sisters & Shop).
NOUVELLE MAQUETTE CANVA de Maeva (25/11/2026, « cible_canva_12_A4 ») reprise TELLE QUELLE :
12 billets / feuille A4 PAYSAGE (3 colonnes x 4 rangées), traits de coupe en pointillés.
Chaque billet : cadre arrondi, pastille « N° », cadre « CIBLE », RANI&HEI 87 77 39 19,
8 CIBLES à fléchette (2 rangées de 4). Le dessin vient de la maquette : image noir & blanc
600 dpi rangée DANS ce fichier, enregistrée UNE fois par document -> fichier léger,
impression d'une traite.
RÈGLE (inchangée, 8 numéros) — rangée du haut : B 1-15 · B 1-15 · I 16-30 · I 16-30
                               rangée du bas  : N 31-45 · N 31-45 · G 46-60 · O 61-75
   (dans chaque paire, le plus petit à gauche) -> crieur 1 à 75.
   La lettre et la plage sont écrites en petit en haut de chaque cible (25/11, demande de Maeva).
Chiffres gras comme la maquette, 28 pt pour rester DANS le rond blanc de la cible.
Le tout est réduit pour garder 6 mm de marge d'impression (Konica / Sharp).
(L'ancien cible.py — 6 cartons portrait — reste dans le dossier, il n'est plus appelé.)"""
import io, os as _os, random
from reportlab.pdfgen import canvas
from reportlab.lib.pagesizes import landscape, A4
from reportlab.lib import colors

PAGE_W, PAGE_H = landscape(A4)
COLS, RANGS = 3, 4
CARTES_PAGE = COLS * RANGS                # 12
CELL_W, CELL_H = 280.6299, 148.8189
NOIR = colors.black
RAINBOW = ["#E53935", "#FB8C00", "#F9A825", "#43A047", "#00ACC1",
           "#1E88E5", "#3949AB", "#8E24AA", "#D81B60", "#6D4C41"]
POLICE_NUM, T_NUM = "Helvetica-Bold", 28
_IMG = _os.path.join(_os.path.dirname(_os.path.abspath(__file__)), "cible_v2_dessin.png")

_XS = (36.85, 100.63, 164.41, 228.19)          # centres des 4 colonnes de cibles
_YC = (83.6, 29.76)                             # centres des 2 rangées
# plages des 8 cibles, dans l'ordre de lecture
PLAGES = [(1, 15), (1, 15), (16, 30), (16, 30), (31, 45), (31, 45), (46, 60), (61, 75)]
LETTRES = ["B", "B", "I", "I", "N", "N", "G", "O"]

MARGE_SURE = 6 * 72 / 25.4
ECHELLE = min((PAGE_W - 2 * MARGE_SURE) / PAGE_W, (PAGE_H - 2 * MARGE_SURE) / PAGE_H)
DECAL_X = (PAGE_W - PAGE_W * ECHELLE) / 2.0
DECAL_Y = (PAGE_H - PAGE_H * ECHELLE) / 2.0
_DEJA = set()


def _image_dessin():
    if _os.path.exists(_IMG):
        return _IMG
    import base64
    from reportlab.lib.utils import ImageReader
    return ImageReader(io.BytesIO(base64.b64decode(_DESSIN_PNG)))


def _numeros(rng):
    for _ in range(400):
        b = sorted(rng.sample(range(1, 16), 2))
        i = sorted(rng.sample(range(16, 31), 2))
        n = sorted(rng.sample(range(31, 46), 2))
        t = (b[0], b[1], i[0], i[1], n[0], n[1], rng.randint(46, 60), rng.randint(61, 75))
        if t not in _DEJA:
            break
    _DEJA.add(t)
    return t


def _txt(c, s, x, y, police, taille, col, esp=0, centre=False):
    w = c.stringWidth(s, police, taille) + (esp * (len(s) - 1) if esp else 0)
    t = c.beginText(x - w / 2.0 if centre else x, y); t.setFont(police, taille)
    if esp:
        t.setCharSpace(esp)
    t.setFillColor(col); t.textOut(s)
    if esp:
        t.setCharSpace(0)
    c.drawText(t)


def _billet(c, ox, oy, serie, nums, col):
    if not getattr(c, "_cible_modele", False):     # le dessin : une seule fois par document
        c.beginForm("CIBLE_DESSIN", 0, 0, CELL_W, CELL_H)
        c.drawImage(_image_dessin(), 0, 0, CELL_W, CELL_H)
        c.endForm()
        c._cible_modele = True
    c.saveState()
    c.translate(ox, oy)
    c.doForm("CIBLE_DESSIN")
    _txt(c, "N\u00b0 %06d" % serie, 22.38822, 129.2598, "Helvetica-Bold", 8.5, NOIR)
    _txt(c, "CIBLE", 110.8309, 123.3071, "Helvetica", 20, NOIR, esp=1)
    _txt(c, "RANI&HEI", 227.2802, 131.811, "Helvetica-Bold", 8, NOIR)
    _txt(c, "87 77 39 19", 225.4833, 120.4724, "Helvetica-Bold", 8, NOIR)
    for k, v in enumerate(nums):
        cx = _XS[k % 4]
        cy = _YC[k // 4]
        _txt(c, str(v), cx, cy - 2.0 - 0.716 * T_NUM / 2.0, POLICE_NUM, T_NUM, col, centre=True)
        lo, hi = PLAGES[k]
        _txt(c, "%s %d-%d" % (LETTRES[k], lo, hi), cx, cy + 12.0, "Helvetica-Bold", 5.5, col, centre=True)
    c.restoreState()


def generer_pdf(nb_cartes=None, nb_tickets=None, serie_start=1, theme="", couleur=True,
                nom_evenement="", titre_jeu="", couleur_perso="", date_lieu="",
                telephone="", page_start=1, evenement_id="", style="", motif="", **_ig):
    n_ = nb_cartes if nb_cartes is not None else nb_tickets
    n_ = max(1, int(n_ if n_ else CARTES_PAGE))
    buf = io.BytesIO()
    c = canvas.Canvas(buf, pagesize=(PAGE_W, PAGE_H), pageCompression=1)
    rng = random.Random(int(serie_start) * 100003 + 1575)
    _DEJA.clear()
    serie = int(serie_start)
    faits = 0
    try:
        no_page = max(1, int(page_start))
    except Exception:
        no_page = 1
    col_imposee = None
    if couleur and couleur_perso:
        try:
            col_imposee = colors.HexColor(couleur_perso)
        except Exception:
            col_imposee = None

    while faits < n_:
        entete = "  \u00b7  ".join(t for t in ((nom_evenement or "").strip(), (date_lieu or "").strip()) if t)
        if entete:
            c.setFillColor(NOIR); c.setFont("Helvetica-Bold", 7)
            c.drawCentredString(PAGE_W / 2.0, PAGE_H - DECAL_Y / 2.0 - 2.5, entete)
        c.setFillColor(colors.Color(0.5, 0.5, 0.5)); c.setFont("Helvetica", 6)
        c.drawRightString(PAGE_W - DECAL_X, DECAL_Y / 2.0 - 2, "page %d" % no_page)

        c.saveState()
        c.translate(DECAL_X, DECAL_Y); c.scale(ECHELLE, ECHELLE)
        for idx in range(CARTES_PAGE):
            if faits >= n_:
                break
            ox = (idx % COLS) * CELL_W
            oy = (RANGS - 1 - idx // COLS) * CELL_H
            col = (col_imposee or colors.HexColor(RAINBOW[serie % len(RAINBOW)])) if couleur else NOIR
            _billet(c, ox, oy, serie, _numeros(rng), col)
            serie += 1
            faits += 1
        c.setStrokeColor(colors.Color(0.5, 0.5, 0.5)); c.setLineWidth(0.3); c.setDash(2, 2)
        for i in (1, 2):
            c.line(i * CELL_W, 0, i * CELL_W, RANGS * CELL_H)
        for j in (1, 2, 3):
            c.line(0, j * CELL_H, COLS * CELL_W, j * CELL_H)
        c.restoreState()
        c.showPage()
        no_page += 1
    c.save()
    buf.seek(0)
    return buf


_DESSIN_PNG = ""


if __name__ == "__main__":
    open("test_cible.pdf", "wb").write(generer_pdf(nb_cartes=12, couleur=False).read())
    print("CIBLE genere")
